class Solution:
    def minSubsequence(self, nums: List[int]) -> List[int]:
        result, total, curr = [], sum(nums), 0
        nums.sort(reverse=True)
        for i, x in enumerate(nums):
            curr += x
            if curr > total-curr:
                break
        return nums[:i+1]
